-- Generated by `prisma migrate dev --create-only`; nullable, so existing rows
-- need no backfill (TravTrack plan T7, Codex review of the share restrictions,
-- fourth round). The first share that commits a pending row (`version` 0)
-- marks it with its own token; a failed build removes the pending row only if
-- it carries that token, and only under the TravTrack lock, so it never takes
-- the row another build is relying on.

-- AlterTable
ALTER TABLE "travtrack_share_snapshots" ADD COLUMN     "build_token" TEXT;
